codeSample:
// JSON (~40 bytes)
{"id": "123", "name": "John Doe"}

// Protobuf 二进制编码 (~15 bytes)
0A 03 31 32 33 12 08 6A 6F 68 6E 20 64 6F 65
// 瘦标签 + 变长编码，字段名不进二进制体

data: {"id": 1, "description": "Event 1"}

data: {"id": 2, "description": "Event 2"}

# 每个 data: 行是独立一条消息，同一条 TCP 连接，浏览器用 EventSource 逐行处理
